package org.apache.commons.compress.archivers.cpio;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.FilterOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.cpio.CpioArchiveOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for CpioArchiveOutputStream.close()
 */
public class CpioArchiveOutputStream_close_TriageGen0Test {

    /**
     * Tests that calling close() on an open stream works correctly.
     * This covers the branch where !this.closed is true.
     */
    @Test
    public void testClose_Success() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (CpioArchiveOutputStream cos = new CpioArchiveOutputStream(baos, CpioArchiveOutputStream.BUILD)) {
            cos.close();
        }
        // If no exception is thrown, the logic executed successfully.
    }

    /**
     * Tests that calling close() multiple times does not throw an exception.
     * This covers the branch where !this.closed is false (the second call).
     */
    @Test
    public void testClose_MultipleTimes() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        CpioArchiveOutputStream cos = new CpioArchiveOutputStream(baos, CpioArchiveOutputStream.BUILD);

        cos.close();
        // Second call should enter the 'if (!this.closed)' check, find it false, and do nothing.
        cos.close(); 
    }

    /**
     * Tests that close() correctly propagates an IOException from the underlying stream.
     * This ensures the super.close() call is actually executed.
     */
    @Test(expected = IOException.class)
    public void testClose_ThrowsIOException() throws IOException {
        OutputStream errorStream = new IOExceptionOutputStream();
        CpioArchiveOutputStream cos = new CpioArchiveOutputStream(errorStream, CpioArchiveOutputStream.BUILD);
        cos.close();
    }

    /**
     * Mock OutputStream that throws an exception on close.
     */
    private static class IOExceptionOutputStream extends OutputStream {
        @Override
        public void close() throws IOException {
            throw new IOException("Simulated close failure");
        }

        @Override
        public void write(int b) throws IOException {
            // No-op
        }
    }
}
